import { SPIRITS, ELEMENT_HAN, RARITY_NAMES, spiritById, type Spirit } from '../data/gameContent';
import { ownedStats, type GameSave } from '../systems/adventure';
import { codexBonus } from '../systems/campaign';
import { acquisition, awakeningRecord, codexList, type CodexView } from './codexPanel';
import { elementBadge, number, portrait, stars } from './components';
import { fullIllustration, pixelSprite } from './pixel';
import { combatStyle } from '../data/combatStyles';
import { idleProfile, idleStyle } from '../data/idleProfiles';
import type { Element } from '../types/unit';

export interface BookView {open:boolean;reading:boolean;motion:'open'|'turn'|'none';direction?:number}
export const newBookView=():BookView=>({open:false,reading:false,motion:'open'});
const esc=(s:string)=>s.replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]!));
const no=(d:Spirit)=>String(SPIRITS.indexOf(d)+1).padStart(3,'0');
const regions=[...new Set(SPIRITS.map(d=>d.region))];
const bookName=(v:CodexView)=>v.tab==='awakening'?'각성비록':'요괴도감';
export function libraryPanel(s:GameSave,v:CodexView,b:BookView){
 if(b.open)return reader(s,v,b);
 return `<section class="spirit-library"><div class="library-art"></div><div class="library-light"></div><header class="library-heading"><span>月下藏書 · 달빛 아래 쌓인 이야기</span><h1>만령서고</h1><p>한 권을 펼치면, 오래된 인연이 깨어납니다.</p></header><div class="library-ledger"><span>인연 <b>${s.owned.length} / ${SPIRITS.length}</b></span><span>각성 기록 <b>${s.owned.reduce((n,u)=>n+u.awakening,0)} / ${SPIRITS.length*5}</b></span><span>도감 공명 <b>+${(codexBonus(s)*100).toFixed(1)}%</b></span><button data-action="codex-rewards">도감 보상 →</button></div><div class="library-desk"><div class="library-featured">${[['base','妖怪圖鑑','요괴도감','65종의 이름과 그들이 품은 이야기','壹'],['awakening','覺醒祕錄','각성비록','다섯 번의 각성, 달라지는 진명의 기록','貳']].map(([id,han,title,desc,n])=>`<button class="closed-volume volume-${id}" data-action="book-open" data-id="${id}" aria-label="${title} 펼치기"><span class="book-binding"></span><span class="volume-corners"></span><span class="volume-han">${han}</span><span class="volume-number">${n}</span><span class="volume-label"><b>${title}</b><small>${desc}</small></span><span class="volume-open">책 펼치기 ↗</span></button>`).join('')}</div><div class="library-shelf-title"><span>경계별 장서</span><i></i><small>그곳에 깃든 요괴를 찾아서</small></div><div class="regional-volumes">${regions.map((r,i)=>`<button class="regional-volume" style="--volume-hue:${125+i*42}" data-action="book-region" data-id="${r}" aria-label="${r} 장서 펼치기"><span>${['壹','貳','參','肆','伍','陸','柒'][i]??'緣'}</span><b>${r}</b><small>${SPIRITS.filter(d=>d.region===r).length}종의 기록</small></button>`).join('')}</div><p class="library-footnote">요괴의 이름을 찾고, 책장을 넘겨 그 이야기를 읽어 보세요.</p></div></section>`;
}
function reader(s:GameSave,v:CodexView,b:BookView){
 return `<section class="library-reader"><div class="reader-toolbar"><button class="outline-button" data-action="book-close">← 책 덮기</button><div><small>만령서고 · ${v.region==='전체'?'전체 장서':v.region}</small><h1>${bookName(v)}</h1></div><button class="outline-button" data-action="book-index">목차 보기</button></div>${b.reading?'':filters(v)}<div id="book-spread">${bookSpread(s,v,b)}</div></section>`;
}
function filters(v:CodexView){
 return `<div class="book-searchbar"><label class="book-search"><span>⌕</span><input id="codex-search" aria-label="도감 이름 검색" placeholder="기록에서 이름 찾기" value="${esc(v.query)}"></label><div class="book-filter-elements" role="group" aria-label="도감 오행 필터">${['전체','목','화','토','금','수'].map(e=>`<button data-action="dex-element" data-id="${e}" aria-pressed="${e===v.element}" class="${e===v.element?'active':''}">${e==='전체'?'전체':ELEMENT_HAN[e as Element]+' '+e}</button>`).join('')}</div></div><div class="book-selects"><label>지역<select id="dex-region"><option value="전체">모든 지역</option>${regions.map(r=>`<option ${r===v.region?'selected':''}>${r}</option>`).join('')}</select></label><label>등급<select id="dex-rarity"><option value="0">모든 등급</option>${[5,4,3,2,1].map(n=>`<option value="${n}" ${n===v.rarity?'selected':''}>${n}성 · ${RARITY_NAMES[n]}</option>`).join('')}</select></label><label>수집<select id="dex-ownership">${[['all','전체 요괴'],['owned','보유 요괴'],['missing','미보유 요괴'],['awakened','각성한 요괴']].map(([id,t])=>`<option value="${id}" ${id===v.ownership?'selected':''}>${t}</option>`).join('')}</select></label><label>정렬<select id="dex-sort">${[['number','도감 번호순'],['rarity','높은 등급순'],['owned','보유 요괴 먼저']].map(([id,t])=>`<option value="${id}" ${id===v.sort?'selected':''}>${t}</option>`).join('')}</select></label><button class="text-link" data-action="dex-reset">필터 초기화</button></div>`;
}
export function bookSpread(s:GameSave,v:CodexView,b:BookView){
 const list=codexList(s,v),pages=Math.max(1,Math.ceil(list.length/18));v.page=Math.max(0,Math.min(v.page,pages-1));
 const theme=regions.indexOf(spiritById(v.selected).region);
 const selected=list.findIndex(d=>d.id===v.selected),entry=b.reading;
 return `<div class="antique-book book-motion-${b.motion} volume-${v.tab} ${entry?'reading-entry':'reading-index'}" style="--page-region-x:${theme%2*100}%;--page-region-y:${Math.floor(theme/2)*50}%;--page-accent:${idleProfile(v.selected).color}" aria-label="${bookName(v)} ${entry?'요괴 기록':'목차'}"><div class="book-ribbon" aria-hidden="true">${v.tab==='base'?'圖鑑':'覺醒'}</div><span class="book-cover-leaf" aria-hidden="true">${bookName(v)}</span><span class="book-turn-leaf" aria-hidden="true"></span><div class="book-spine" aria-hidden="true"></div>${entry?entryPages(s,v):indexPages(s,v,list)}</div><div class="book-bottom"><button class="outline-button" data-action="${entry?'book-prev':'dex-page'}" data-id="${v.page-1}" ${entry?selected<=0?'disabled':'':v.page===0?'disabled':''}>← ${entry?'이전 기록':'이전 책장'}</button><span role="status">${entry?`No. ${no(spiritById(v.selected))} · ${bookName(v)}`:`${list.length}종의 기록 · ${v.page*2+1}–${v.page*2+2}쪽 / ${pages*2}쪽`}</span><button class="outline-button" data-action="${entry?'book-next':'dex-page'}" data-id="${v.page+1}" ${entry?selected>=list.length-1?'disabled':'':v.page>=pages-1?'disabled':''}>${entry?'다음 기록':'다음 책장'} →</button></div>`;
}
function indexPages(s:GameSave,v:CodexView,list:Spirit[]){
 const visible=list.slice(v.page*18,(v.page+1)*18);
 return [0,1].map(side=>`<article class="paper-page index-page"><div class="paper-running-title"><span>${bookName(v)}</span><span>萬靈書庫</span></div><div class="index-heading-ornament"><span>目錄</span><h2>${side===0?'인연의 목차':'기록의 갈피'}</h2><small>그 이름에 머무는 이야기</small></div><div class="book-index-list">${visible.slice(side*9,side*9+9).map(d=>{const u=s.owned.find(x=>x.id===d.id);return `<button class="book-index-entry" data-action="book-entry" data-id="${d.id}" aria-label="${d.name} ${v.tab==='awakening'?'각성 기록':'요괴 기록'} 읽기"><span class="index-portrait">${portrait(d,'',v.tab==='awakening'?5:0)}</span><span class="index-copy"><small>第 ${no(d)} 記 · ${d.region}</small><b>${d.name} <i>${ELEMENT_HAN[d.element]}</i></b><span>${RARITY_NAMES[d.rarity]} · ${d.role}</span></span><span class="index-status ${u?'found':''}">${v.tab==='awakening'?`${u?.awakening??0} / 5`:u?'인연':'미발견'}<i>↗</i></span></button>`;}).join('')||`<div class="paper-empty"><span>緣</span><p>${list.length?'다음 인연을 기다리는 빈 책장':'이 조건의 기록을 찾지 못했습니다.'}</p>${!list.length?'<button data-action="dex-reset">필터 초기화</button>':''}</div>`}</div><span class="paper-number">${v.page*2+side+1}</span></article>`).join('');
}
function entryPages(s:GameSave,v:CodexView){
 const d=spiritById(v.selected),u=s.owned.find(x=>x.id===d.id),awake=v.tab==='awakening',stage=awake?v.stage:0,r=awakeningRecord(s,d.id,stage),stats=ownedStats(s,d.id),style=combatStyle(d.id);
 return `<article class="paper-page illustration-page"><div class="paper-running-title"><span>第 ${no(d)} 記</span><span>${bookName(v)}</span></div><div class="ink-chapter-seal" aria-hidden="true">${ELEMENT_HAN[d.element]}</div><h2>${d.name}</h2><p class="book-art-title">${d.title}</p><div class="illuminated-plate" data-idle="${idleProfile(d.id).kind}" style="${idleStyle(d.id)}"><div class="plate-landscape"></div><span class="plate-orbit"></span><span class="plate-inscription">${d.region} · ${RARITY_NAMES[d.rarity]}</span><button class="book-full-art" data-action="book-art" data-id="${d.id}" aria-label="${d.name} 전신 일러스트 크게 보기">${fullIllustration(d.id,stage)}</button><span class="plate-petal p1"></span><span class="plate-petal p2"></span><span class="plate-petal p3"></span></div><p class="book-quote">“${d.quote}”</p><span class="book-art-hint">그림을 누르면 크게 볼 수 있습니다</span><span class="paper-number">${Number(no(d))*2-1}</span></article><article class="paper-page biography-page"><div class="paper-running-title"><span>${d.region}</span><span>${ELEMENT_HAN[d.element]} · ${d.role}</span></div><div class="book-entry-meta">${elementBadge(d.element)}${stars(d.rarity)}<span>${u?'인연을 맺은 요괴':'아직 만나지 못한 인연'}</span></div>${awake?`<h2>각성의 다섯 기록</h2><div class="book-stage-tabs" role="group" aria-label="각성 단계 선택">${[1,2,3,4,5].map(n=>`<button data-action="dex-stage" data-id="${n}" aria-pressed="${stage===n}" class="${stage===n?'selected':''}"><b>${n}각성</b><small>${(u?.awakening??0)>=n?'해금':'미해금'}</small></button>`).join('')}</div><span class="paper-stamp">${r.unlocked?'해금한 기록':'미해금 · 미리보기'}</span><h3>${['첫 울림','깊어진 인연','영혼의 결','경계를 넘어','진명의 개화'][stage-1]}</h3><p class="book-lore">${stage===5?(r.hasNewArt?'잠들어 있던 진명이 깨어나며, 일러스트와 전투 모습이 달라집니다.':'진명의 오라가 피어나, 영혼을 감싸는 빛이 한층 깊어집니다.'):'오래된 인연이 힘이 되어, 요괴의 잠든 가능성을 한 겹씩 깨웁니다.'}</p><dl class="paper-stats"><div><dt>누적 능력치 보너스</dt><dd>+${r.bonus}%</dd></div><div><dt>레벨 상한</dt><dd>Lv. ${r.cap}</dd></div><div><dt>스킬 1 / 스킬 2 계수</dt><dd>${r.coefficients.skill1}% / ${r.coefficients.skill2===null?'—':r.coefficients.skill2+'%'}</dd></div><div><dt>궁극기 계수</dt><dd>${r.coefficients.ultimate}%</dd></div></dl><p class="book-small">각성만 반영한 누적 효과 · 장비·돌파·공명 별도</p><div class="book-requirement"><b>${stage-1} → ${stage}각성 재료</b><p>Lv. ${r.requiredLevel} · 금화 ${number(r.gold)}<br>전용 각성석 ${r.stones} · 혼돈 파편 ${r.stones}</p></div><p class="book-small">${d.atlas==='spirits'?'1~4각성은 기본 외형, 5각성은 전용 외형입니다.':'이 요괴의 5각성은 기존 외형에 진명 오라가 더해집니다.'}</p>`:`<h2>이름에 깃든 이야기</h2><p class="book-lore">${d.flavorText}</p><div class="paper-rule"></div><h3>${d.skill}</h3><p class="book-lore">${d.role==='치유'?'체력이 낮은 아군 2명을 치유합니다.':d.role==='수호'?'적을 공격하고 아군 전열에 보호막을 부여합니다.':d.role==='술사'?'적 진영 전체에 오행 피해를 줍니다.':'전열의 적에게 강력한 오행 피해를 줍니다.'}</p><h3>${d.ultimate} <small>궁극기</small></h3><p class="book-lore">${d.role==='치유'?'아군 전체에 대규모 치유를 베풉니다.':d.role==='수호'?'적 전체 공격과 함께 아군 전체를 보호합니다.':'적 전체에 강력한 오행 피해를 줍니다.'}</p><dl class="paper-stats"><div><dt>${u?`Lv. ${u.level} 보유 능력치`:'미보유 기본 능력치'}</dt><dd>${d.role}</dd></div><div><dt>생명 / 공격 / 방어</dt><dd>${number(stats.hp)} / ${number(stats.atk)} / ${number(stats.def)}</dd></div></dl><p class="book-acquisition">인연을 만나는 곳 · <b>${acquisition(d)}</b></p>`}<div class="book-battle-form"><div class="book-idle-stage"><span class="idle-platform"></span>${pixelSprite(d.id,'',stage)}</div><div><small class="idle-label">살아 숨 쉬는 인연 · 대기 모션</small><strong>${style.weapon}</strong><p>${idleProfile(d.id).description}</p><small>전투 모습${awake?` · ${stage}각성`:''}</small></div></div><div class="book-entry-actions"><button class="primary-button" data-action="${u?'detail':d.storyOnly?'world':'go-summon'}" data-id="${d.id}">${u?'요괴 성장으로':d.storyOnly?'합류할 여정 보기':'소환 상점으로'}</button><button class="outline-button" data-action="book-switch">${awake?'요괴도감에서 읽기':'각성비록에서 읽기'}</button></div><span class="paper-number">${Number(no(d))*2}</span></article>`;
}
