export function generalCounter(s:GameSave){return `<header class="general-heading"><div><span>GRANDMOTHER’S GOODS</span><h2>여행자의 준비물</h2><p>다음 여정에 필요한 것들을 챙겨 가렴.</p></div><button class="outline-button" data-action="shop-tab" data-id="exchange">각성 재료 교환 →</button></header><div class="general-goods">${SHOP_GOODS.map(g=>`<article class="goods-card"><span class="goods-category">${g.category}</span>${goodsArt(g.icon)}<h3>${g.name}</h3><p>${g.desc}</p><div class="goods-owned">${g.unit} <b>${number(shopStock(s,g.id))}${g.id==='herbal-tea'?` / ${staminaCap(s)}`:''}</b></div><button class="goods-buy" data-action="buy-review" data-id="${g.id}" ${purchaseProblem(s,g.id,1)?'disabled':''}><span>${g.id==='herbal-tea'?'한 잔 마시기':'구매하기'}</span><b>${icon(g.currency==='gold'?'gold':'gem',16)} ${number(g.price)}</b></button></article>`).join('')}</div><p class="general-note">약차는 즉시 사용됩니다. 다른 물품은 보유 재료에 더해집니다.</p>`;}
export function purchaseReview(s:GameSave,id:string,quantity:number){const g=SHOP_GOODS.find(g=>g.id===id);if(!g)return '<p>상품을 찾지 못했습니다.</p>';const error=purchaseProblem(s,id,quantity),amount=g.id==='herbal-tea'?Math.min(30,staminaCap(s)-s.stamina):g.amount*quantity;return `<div class="goods-review"><small>인연 할머니의 일반 상점</small><h2>${g.name}</h2>${goodsArt(g.icon)}<p>${g.desc}</p>${g.id!=='herbal-tea'?`<div class="goods-quantity"><button data-action="buy-quantity" data-id="${quantity-1}" ${quantity<=1?'disabled':''} aria-label="구매 수량 줄이기">−</button><span>${quantity}묶음</span><button data-action="buy-quantity" data-id="${quantity+1}" ${quantity>=5?'disabled':''} aria-label="구매 수량 늘리기">＋</button></div>`:''}<dl><div><dt>${g.unit} ${g.id==='herbal-tea'?'실제 회복':'획득'}</dt><dd>+${amount}</dd></div><div><dt>사용 ${g.currency==='gold'?'금화':'경계석'}</dt><dd>${number(g.price*quantity)}</dd></div><div><dt>구매 후 남는 재화</dt><dd>${number(Math.max(0,s[g.currency]-g.price*quantity))}</dd></div></dl>${error?`<p class="goods-error">${error}</p>`:''}<div class="button-row"><button class="outline-button" data-action="close">돌아가기</button><button class="primary-button" data-action="buy-confirm" data-id="${g.id}" ${error?'disabled':''}>${g.id==='herbal-tea'?'약차 마시기':'구매 확정'}</button></div></div>`;}
